import{_ as r,a0 as p,w as l,s as o,ao as s,I as i,x as u,a1 as n,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧：解决VirtualBox中截屏时的黑屏故障 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧：解决VirtualBox中截屏时的黑屏故障 | LCTT (201404) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧：解决VirtualBox中截屏时的黑屏故障 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧：解决VirtualBox中截屏时的黑屏故障 | LCTT (201404) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201404/Daily Ubuntu Tips – Fix Black Screen In Ubuntu Guest With VirtualBox Screen Capture","title":"每日Ubuntu小技巧：解决VirtualBox中截屏时的黑屏故障","tag":"201404","desc":""},"relativePath":"201404/Daily Ubuntu Tips – Fix Black Screen In Ubuntu Guest With VirtualBox Screen Capture.md","filePath":"[post].md"}'),b={name:"201404/Daily Ubuntu Tips – Fix Black Screen In Ubuntu Guest With VirtualBox Screen Capture.md"};function x(d,t,T,m,U,g){const e=p("Link");return l(),o("div",null,[t[11]||(t[11]=s('<h1 id="每日ubuntu小技巧-解决virtualbox中截屏时的黑屏故障" tabindex="-1">每日Ubuntu小技巧：解决VirtualBox中截屏时的黑屏故障 <a class="header-anchor" href="#每日ubuntu小技巧-解决virtualbox中截屏时的黑屏故障" aria-label="Permalink to “每日Ubuntu小技巧：解决VirtualBox中截屏时的黑屏故障”">​</a></h1><p>VirtualBox是一个可以让你在一台物理主机上运行多个系统的软件。它支持Windows,Mac OS X 和Linux 并且是Oracle公司在维护它。</p><p>我们在这里写了很多关于VirtualBox的文章，你可以做一个快速的查找来查看所有关于VirtualBox的文章。</p><p>现在，这里有一个故事：VirtualBox有一个功能，允许用户快速的截取虚拟机会话的屏幕截图。这些截图可以通过粘贴板和宿主机共享。</p><p>这就是我们这里要说的了。当某一个Ubuntu 虚拟机中的功能启用后，这项截图的功能就不能够正常的工作了。这种现象一直是一个痛点，直到最近我们偶然发现了这个解决方法。</p><p>如果不采取我们发现的这个方法，当你在Ubuntu的虚拟机里面截完屏幕之后，截屏的图片将会被存储成全黑的文件，这样的文件会毫无用处。</p><p>我一直在苦苦寻找解决方法，但是一直都没有好运气，直到刚刚。</p><p>要开启Ubuntu下的虚拟机和宿主机之间的双向黏贴板的话，请在Ubuntu虚拟机上面点击 “设置”，之后找到“普通-&gt;高级标签”，选择这个功能来开启它。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/02/virtualboxsharedclipboard.png" alt=""></p><p>现在，理论上，当你开启Ubuntu的虚拟机之后，按下“截屏键”，或者按下“Ctrl+截屏键”，虚拟机就应该为当前的桌面会话来张截屏。</p><p>之后你就可以通过在宿主机上面使用粘贴板的功能来看到那些图片了。</p><p><strong>但是！</strong>如果你同时启用了Ubuntu虚拟机中的“3D 加速”功能，那些图片将会变得漆黑一片。</p><p>为了解决这个问题，你必须关闭Ubuntu虚拟机的3D加速功能！</p><p>关闭3D加速功能可以这样做：在Ubuntu虚拟机种点击“设置”，之后找到“系统-&gt;显示-&gt;显卡”标签，关闭3D加速</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2014/02/virtualboxsharedclipboard1.png" alt=""></p><p>现在你必须在Ubuntu的虚拟机中设置关闭3D加速才能让截屏正常工作。现在打开一个虚拟机尝试来截个屏幕吧。</p><p>希望这个方法能够帮到你！</p><p>希望你喜欢！</p><hr>',19)),i("p",null,[t[1]||(t[1]=u("via: ",-1)),n(e,{href:"http://www.liberiangeek.net/2014/02/daily-ubuntu-tips-fix-black-screen-in-ubuntu-guest-with-virtualbox-screen-capture/"},{default:a(()=>[...t[0]||(t[0]=[u("http://www.liberiangeek.net/2014/02/daily-ubuntu-tips-fix-black-screen-in-ubuntu-guest-with-virtualbox-screen-capture/",-1)])]),_:1})]),i("p",null,[t[4]||(t[4]=u("译者：",-1)),n(e,{href:"https://github.com/%E8%AF%91%E8%80%85ID"},{default:a(()=>[...t[2]||(t[2]=[u("FineFan",-1)])]),_:1}),t[5]||(t[5]=u(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[3]||(t[3]=[u("wxy",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=u("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[6]||(t[6]=[u("LCTT",-1)])]),_:1}),t[9]||(t[9]=u(" 原创翻译，",-1)),n(e,{href:"http://linux.cn/"},{default:a(()=>[...t[7]||(t[7]=[u("Linux中国",-1)])]),_:1}),t[10]||(t[10]=u(" 荣誉推出",-1))])])}const C=r(b,[["render",x]]);export{w as __pageData,C as default};
